/* Form wording — generated from the HCS onboarding packet. Do not edit by hand. */
window.HCS_DOCS = {"coe": [["title", "Condition of Employment"], ["p", "Dear Employee,"], ["p", "Home Care Solutions, LLC is considering an offer of employment to you as a Personal Care Aide (PCA) to be assigned to one of our various clients. This position is temporary and not guaranteed due to the nature of our business."], ["p", "Your employment is contingent upon the completion of applicable Federal and State requirements; and any additional provisions as required by the position."], ["p", "As a PRN employee, assignments are based on availability and will change as client and business needs dictate. If this is agreeable to you, you may please sign in the appropriate employee section below."], ["p", "You are welcome to Home Care Solutions."], ["p", "My regards,"]], "jd": [["title", "Job Description: PCA (Personal Care Aide) / CNA"], ["ul", "Provide or assist with any of the appropriate duties that do not require complex observation or critical decision making."], ["ul2", "Personal care"], ["ul2", "Housekeeping"], ["ul2", "Ambulation"], ["ul2", "Home management"], ["ul2", "Nutrition"], ["ul", "Encourage member to make decisions and to remain as independent as possible."], ["ul", "Encourage member representative to be involved and responsible for care of the member."], ["ul", "Complete the Member Service Record or EVV after each visit for each member."], ["ul", "Observe and report changes in member's condition and support system including meal consumption, food storage and cooking equipment failure to the supervisor."], ["ul", "Adhere to written code of ethics and dress code."], ["ul", "Assisting with activities of daily living, such as bathing, dressing, grooming, toileting, mobility, eating, positioning, transferring, skin care, and communication as required."], ["ul", "Provide care to the member as outlined in the Plan of Care by the RN. The task may include range of motion and muscle maintenance exercise."], ["ul", "Attend medical appointment with the member as required."], ["ul", "Assist with homemaking activities such as meal preparation and clean-up, house duties for the member's areas only, laundry and shopping (this does not include laundry or cleaning for other members, nor mowing and raking the lawn)."], ["ul", "Observe member's skin for any break down or potential break down and report immediately to the nurse any change in the member's skin condition."], ["ul", "In the event of a life-threatening emergency, provide CPR where necessary and call 911."], ["ul", "Follow the Provider's emergency procedure for all other known emergencies."]], "ethics": [["title", "Personnel Code of Ethics"], ["p", "The manner in which Home Care Solutions employs and conducts business is extremely important to our success. We have corporate responsibilities to ourselves, our clients and the communities in which we do business. In order to effectively provide premiere care and protect our corporate and professional image, we must strive to conduct our business in the most ethical manner."], ["p", "Each employee is expected to read, understand, sign, date and comply with the company's code of ethics. This will be retained in their personal file to be reviewed annually."], ["p", "<b>The following standards will be adhered to with no exceptions:</b>"], ["ol", "Staff shall not enter into a personal relationship with their clients"], ["ol", "Staff shall not give clients their home residence phone number — clients will be encouraged to call the central phone number for assistance after regular office hours"], ["ol", "Staff shall not discriminate against any consumer or visitor based on race, religion, sexual orientation, economic conditions, or mental and physical challenges"], ["ol", "Staff shall protect the rights of all clients by safeguarding clients' physical safety at all times"], ["ol", "Staff shall not use client's car for personal reasons"], ["ol", "Staff shall not consume client's food or beverage"], ["ol", "Staff shall not use client's telephone for personal calls"], ["ol", "Staff shall not discuss political or religious beliefs, or personal problems with the client"], ["ol", "Staff shall not accept gifts or financial gratuities (tips) from the client or client's representative"], ["ol", "Staff shall not lend money or other items to the client; borrow money or other items from the client or client's representative"], ["ol", "Staff shall not sell gifts, food, or other items to or for the client"], ["ol", "Staff shall not purchase any items for the client unless directed in client care plan"], ["ol", "Staff shall not bring other visitors (e.g., children, friends, relatives, pets, etc.) to the client's home"], ["ol", "Staff shall not smoke in the client's home"], ["ol", "Staff shall not report for duty under the influence of alcoholic beverages or illegal substances"], ["ol", "Staff shall not sleep in the client's home"], ["ol", "Staff shall not remain in the client's home after services have been rendered"], ["attest", "I, the undersigned, have read and fully understand the Ethics Policy of HCS and will abide by the policy."]], "rights": [["title", "Clients Rights and Responsibilities"], ["p", "The Nursing or Care Manager shall review with the client or client representative their rights and responsibilities at the time of the face-to-face evaluation and sign the document. The client is to retain a copy and the Nursing or Care Manager places one in the client's file to be returned and filed in the office."], ["h", "Client's rights recognized by HCS include:"], ["ol", "The right of access to accurate and easy-to-understand information"], ["ol", "The right to be treated with respect and to maintain one's dignity and individuality"], ["ol", "The right to voice grievances and complaints regarding treatment or care that is furnished or not furnished, without fear of retaliation, discrimination, coercion, or reprisal"], ["ol", "The right to a choice of approved service provider(s) and the right to accept or refuse services"], ["ol", "The right to be informed of and participate in preparing the care plan and any changes in the plan"], ["ol", "The right to be advised in advance of the provider(s) who will furnish care and the frequency and duration of visits"], ["ol", "The right to confidential treatment of all information, including information in the client record"], ["ol", "The right to receive services in accordance with the current care plan"], ["ol", "The right to be informed of the name, business telephone number and business address of the person supervising the services and how to contact that person (Department of Human Resources) 2 Peachtree St., N.W., Atlanta, GA 30303 (404) 657-5728"], ["ol", "The right to have property and residence treated with respect. The right to review client's records on request"], ["ol", "The right to be fully and promptly informed of any cost share liability and the consequences if not paid"], ["ol", "The right to receive adequate and appropriate care and services without discrimination"], ["ol", "The right to be free from mental, verbal, sexual and physical abuse, neglect, exploitation, isolation, corporal or unusual punishment, including interference with daily functions of living"], ["ol", "The right to be free from chemical or physical restraints"], ["h", "Client's responsibilities recognized by HCS include:"], ["ol", "The responsibility to notify HCS of any changes in care needs"], ["ol", "The responsibility to treat HCS staff in a courteous and respectful manner, as well as cooperate with and respect the rights of the caregivers providing care"], ["ol", "The responsibility to be as accurate as possible when providing information on health history and personal care needs"], ["ol", "The responsibility to participate actively in decisions regarding individual healthcare and service/care plan"], ["ol", "The responsibility to comply with agreed-upon care plans"], ["ol", "The responsibility to notify the client's physician, service provider(s), and/or caregiver of any change in one's condition"], ["ol", "The responsibility to maintain a safe home environment or to inform provider(s) of the presence of any safety hazard"], ["ol", "The responsibility to be available to provider staff at times services are scheduled to be rendered"], ["ol", "The responsibility to pay any cost share liability, if applicable"], ["ol", "The responsibility to avail the member to the utilization review team to make visits as needed"], ["ol", "The responsibility to maintain a safe environment for self and staff, including a drug free environment at all times. If present in the home, alcohol must be concealed and must not interfere with the service delivery process"], ["ol", "The responsibility to not willfully have utilities (gas, water, electricity) disconnected for non-payment, or other reasons within the member's control"], ["ol", "The responsibility of the member or member's representative to notify the case manager of any changes in his or her Medicaid status"]], "protection": [["title", "Client Protection Assurances / Client Rights"], ["p", "HCS acknowledges that all clients have rights and responsibilities regarding participation in the ICWP program. It is the company's policy that all clients shall be made to feel free and protected from abuse, neglect, mistreatment or financial exploitation. Each client shall receive a copy of the rights and responsibilities for their record and review. HCS shall also retain a signed copy in the client's file."], ["ul", "HCS shall screen each potential employee for criminal background history."], ["ul", "HCS shall not employ individuals with a prior conviction on charges of abuse, neglect, mistreatment or financial exploitation from performing direct client care duties."], ["ul", "We also check employment references / verification (Appendix D)."], ["ul", "Provide in-service training at least annually to all employees, subcontractors, and volunteers on how to recognize situations of possible abuse, neglect, exploitation, and/or the likelihood of serious physical harm to individuals who receive services through the CCSP."], ["ul", "Observe at least annually staff providing direct care to clients and correct any deficiencies via training and warning or possibly termination of employee."], ["ul", "Report verbally all allegations of mistreatment, abuse, neglect, exploitation, elopement, unexpected death, serious injury, injuries of unknown origin, and any other critical event/situation immediately (within 24 hours of the event) to the administrator and to CCSP, AAA and Police for thorough investigation of all alleged client protection violations."], ["ul", "Within three days of the verbal notification of the incident to the CCSP office, HCS shall submit a follow-up Community Care Notification Form (CCNF) to the care coordinator."], ["ul", "Prevent further potential abuse while the investigation is in progress by replacing the care provider with another credible employee. Take appropriate actions if alleged violation is substantiated by discharging the employee or warning depending on the severity of the incident. The accused aide and office staff shall write a comprehensive report of the incident using appropriate instruments — Incident Report Forms (Appendix F). All such incidents are logged in the INCIDENT LOG BOOK, and the alleged violation is thoroughly investigated and reported to the CCSP care coordinator within 5 days."], ["ul", "Complete the investigation within five (5) business days of the incident and submit a written report of the findings to the administrator and to other officials in accordance with state law."], ["h", "Investigation of Allegation"], ["ul", "The Nurse Manager (RN) will go for an assessment of the client to ensure that client is safe to continue receiving services at home. If client's safety is assured, the aide will be taken off the case immediately and replaced with another aide. The accused aide and the office staff are expected to write comprehensive reports of the incident using appropriate instruments — Incident Report Forms (Appendix F). All such incidents are logged in the INCIDENT LOG BOOK, and the alleged violation is thoroughly investigated and reported to the CCSP care coordinator within 5 days."], ["ul", "If allegations are substantiated, appropriate disciplinary actions are taken. First, the aide's appointment is terminated and further the Aide is reported to the law enforcement agency."], ["ul", "Appropriate steps such as counseling, staff training and client education are taken in order to prevent future occurrence."]], "infection": [["title", "Infection Control"], ["p", "HCS staff shall observe the following procedures in the provision of services to prevent exposure to infectious disease. These procedures are universal precautions to prevent the spread of infectious diseases in compliance with Occupational Safety and Health Administration requirements (OSHA) and state regulations for home care providers. All blood and body fluids with blood are to be treated as potentially infectious. General rule of thumb is hand washing before and after attending to client. Wash hands and other skin surfaces immediately and thoroughly if soiled with blood or body fluids, and change gloves after contact with each client. Wash hands before and after giving care to clients. The administrator is responsible for ensuring that infection control is practiced."], ["h", "Wear latex gloves when:"], ["ul", "Touching blood/body fluids, mucous membranes, or non-intact skin."], ["ul", "Handling items or surfaces soiled with blood/body fluids visible with blood."], ["ul", "Performing venipuncture and other vascular access procedures."], ["ul", "Cleaning and decontaminating spills of blood/body fluids."], ["ul", "Although no diseases are known to be spread by direct skin contact with feces or other body fluids, gloves should be worn when having contact with feces and any body fluids as a basic hygiene measure."], ["h", "Standard housekeeping cleaning procedures to be used:"], ["ul", "For spills of blood and body fluids, wipe up spill with soap and water and then disinfect area with a commonly used germicide or freshly prepared 1:10 bleach solution (1 part bleach to 10 parts water)."], ["ul", "All soiled linen should be bagged at the location where it was used; it should not be sorted or rinsed in client-care areas. Linen soiled with blood or body fluids should be placed and transported in bags that prevent leakage."], ["ul", "Linens and personal clothing items laundered should be washed using routine laundering procedures."], ["ul", "Dish washing using routine cleaning procedures effectively destroys pathogenic (disease causing) organisms. Dishes of clients with hepatitis B or AIDS do not need to be separated from the rest of the facility clients. Do not share unwashed utensils or use common drinking glasses with any client."], ["h", "Environmental procedures to be used:"], ["ul", "Use a gown or apron during procedures that are likely to generate splashes of blood or other body fluids. Universal precautions also recommend the use of masks/eye wear during procedures that are likely to generate droplets of blood or other body fluids to prevent exposure of the mucous membrane of the mouth and nose/eyes."], ["ul", "Dispose of secretions directly into the toilet. An individual toilet for a client is not required, but is recommended if the person has diarrhea."], ["ul", "Care should be taken to prevent injuries caused by needles and other sharp instruments or devices."], ["ul", "To prevent needle stick injuries, needles should not be recapped, purposely bent or broken by hand, removed from disposable syringes, or otherwise manipulated by hand. After they are used, disposable syringes and needles, and other sharp items should be placed in puncture-resistant containers for disposal. The puncture-resistant containers should be located as close as practical to the use area."], ["ul", "Direct mouth-to-mouth contact is not recommended. It is recommended that mouthpieces, ventilation bags or other ventilation devices be kept in areas where the need is predictable. However, if such devices are not available an employee should not hesitate to provide CPR (Cardiopulmonary Resuscitation) procedures."], ["attest", "I AM CPR &amp; TB CERTIFIED. I WILL REPORT TO HOME CARE SOLUTIONS ANY EXPOSURE TO TB &amp; HEPATITIS B, WHETHER THE EXPOSURE OCCURRED ON OR OFF THE JOB. I SHALL REPORT THE EXPOSURE IMMEDIATELY WHEN I BECOME AWARE OF IT."]], "abuse": [["title", "Abuse Statement"], ["p", "I, the employee named above, attest that I have never been shown by credible evidence (e.g. a court or jury, a department investigation, or other reliable evidence) to have abused, neglected, assaulted, exploited, or deprived any person or to have subjected any person to serious injury as a result of intentional or gross negligent misconduct as evidenced by an oral or written statement to this effect obtained at the time of application;"], ["p", "That I have participated in the orientation and training required by these rules;"], ["p", "That I have not made any material false statements concerning qualifications requirements either to the department or to HCS."]], "policies": [["title", "Company Policies"], ["p", "These company policies help us to achieve operational excellence and a professional work environment. As such, policy violations are taken seriously and may result in disciplinary actions as follows:"], ["ol", "Verbal Warning"], ["ol", "Written Warning"], ["ol", "Employment Termination"], ["h", "HIPAA"], ["p", "Federal law protects client confidentiality, making it both illegal and unacceptable to share any client's personal information without their explicit consent. Staff members receive client-related information strictly on a need-to-know basis to support their work. By signing, I understand and agree to follow this policy."], ["initials", "Policy 01 HIPAA Initials"], ["h", "NON-DISCLOSURE OF COMPANY INFORMATION"], ["p", "As an employee of Home Care Solutions LLC, I understand that during my employment, I may become aware of confidential company information, including:"], ["p", "1. <i>Technical information:</i> methods, processes, systems, techniques, computer programs, and projects.<br/>2. <i>Business information:</i> client lists, client data, employee records, pricing, payroll, sources of supply, marketing strategies, production methods, or merchandising plans."], ["p", "I agree that both during and after my employment, I will not disclose or share any such confidential information in violation of this agreement. Upon separation from the company, I will promptly return all company documents and property obtained during my employment, without retaining any copies or digital reproductions. The company reserves the right to inform any future or prospective employer of any breach of this agreement."], ["p", "In the event of a breach, the company retains full rights to seek injunctive relief, in addition to any other applicable legal remedies, without prejudice. By signing, I understand and agree to follow this policy."], ["initials", "Policy 02 Non-Disclosure of Company Information Initials"], ["h", "TIME CAPTURE FOR PAYROLL"], ["p", "The company tracks employee hours electronically, recording time worked with clients according to the assigned schedule. Each shift requires the Aide to clock-in at the beginning and clock-out at the end using the company App, as instructed. To use this feature, the Aide must install the App on a functioning smartphone. If there is ever a day without proper clock in/out records, it will be treated as a no-show and will not be paid. By signing, I understand and agree to follow this policy."], ["initials", "Policy 03 Time Capture for Payroll Initials"], ["h", "DRESS CODE"], ["p", "Aides must wear clean, neat, ironed scrubs (any color), a name tag, and closed-toe shoes (no sandals or open-toe footwear) for health, safety and to maintain proper cleanliness and grooming. Aides represent the company, so inappropriate dress is not allowed. By signing, I understand and agree to follow this policy."], ["initials", "Policy 04 Dress Code Initials"], ["h", "TAKING CASH FROM CLIENTS"], ["p", "Aides must never accept cash, credit, or debit cards from clients in any situation. Doing so is considered unprofessional and financial abuse by Adult Protective Services. If a client needs to make a purchase, you may accompany them, get a receipt, and return it to the client. You must consult the office before taking any action outside standard procedures. By signing, I understand and agree to follow this policy."], ["initials", "Policy 05 Taking Cash from Clients Initials"], ["h", "FINGERPRINT AUTHORIZATION AND DEDUCTION"], ["p", "A state-mandated fingerprint criminal background check will be conducted prior to the confirmation of employment. I understand that an unsatisfactory report may result in termination of employment in accordance with state protocols. If necessary, I hereby authorize the company to cover the cost of the background check and deduct the amount from payroll as indicated below (please select one):"], ["choice", "Policy Fingerprint Deduction"], ["p", "By signing, I understand and agree to follow this policy."], ["initials", "Policy 06 Fingerprint Authorization and Deduction Initials"], ["h", "CLIENT HOSPITALIZATION"], ["p", "The Aide must inform the office if a client is admitted to the hospital. Services are suspended during admission, except for routine daytime check-up appointments. By signing, I understand and agree to follow this policy."], ["initials", "Policy 07 Client Hospitalization Initials"], ["h", "NO-SHOW"], ["p", "It is recommended to plan your absence from work in advance to allow the office to provide coverage, where necessary. However, if for any reason you are unable to report for work, you will notify the office immediately. By signing, I understand and agree to follow this policy."], ["initials", "Policy 08 No-Show Initials"], ["h", "STAYING IN CONTACT WITH THE OFFICE"], ["p", "Aides must provide a current contact phone number, preferably a cell phone. The office must be able to reach you at any time during your work schedule. Notify the office immediately of any change in telephone, address or email. By signing, I understand and agree to follow this policy."], ["initials", "Policy 09 Staying in Contact with the Office Initials"], ["h", "QUITTING"], ["p", "Employees are expected to provide two weeks' notice prior to resigning from their position. Not providing appropriate notice may be interpreted as neglect of responsibilities and abandonment of client commitments. By signing, I understand and agree to follow this policy."], ["initials", "Policy 10 Quitting Initials"], ["h", "COMPANY 401K INCENTIVE"], ["p", "All employees are automatically enrolled in the company-sponsored 401K plan after 90 days of employment. If you wish to opt out of participation, please contact ADP to initiate cancellation. By law, ADP will send update letters to all employee addresses by mail. To avoid a fee of up to $15 per mailed letter, you must contact ADP via 800-929-2170 to request free email service. By signing, I understand and agree to follow this policy."], ["initials", "Policy 11 Company 401K Incentive Initials"], ["attest", "I have read each policy above, initialed each one, and agree to follow them."]], "dd": [["title", "Direct Deposit Information"], ["choice", "DD Account Type"], ["choice", "DD Account Holder"], ["h", "AUTHORIZATION FOR DIRECT DEPOSIT, PAY CARD OR PAPER CHECK"], ["p", "I hereby authorize Home Care Solutions, LLC (hereinafter \"Company\") to deposit any amount owed to me for wages and/or reimbursements by initiation of credit entries to my account at the financial institution (hereinafter \"Bank\") handling my choice indicated above. Further, I authorize Bank to accept and credit any credit entries indicated by Company to my account. In the event that Company deposits funds erroneously into my account, I authorize Company to debit my account for an amount not to exceed the original amount of the erroneous credit. This authorization is to remain in full force and effect until Company receives written notice from me of its termination in such time and in such a manner as to afford a reasonable opportunity to act on it. If my method of payment is pay card, as the pay card holder, it is my responsibility to close this account should I no longer choose to have payments deposited in this manner. If I selected Paper Check, I understand that it is impossible to guarantee the date that my paper check will arrive. Home Care Solutions is not responsible for any delays or misdirected mail after checks have been submitted to the U.S. Postal Service. If my paper check does not arrive within 5 business days of payday, I can call Home Care Solutions to issue a stop payment and have a new check issued. I understand that if I request a stop payment, a processing fee of $35.00 will be deducted from my new check. If I require that this fee be waived, I must sign up for either direct deposit or a Pay Card."], ["p", "Return completed form by email to: hcsllc2@gmail.com, or by fax to 678-364-7955."]]};
